<style>
:root{font-family:system-ui,'Segoe UI',sans-serif;color:#e8f4ff;background:#06132d}*{box-sizing:border-box}body{margin:0}button,input,textarea,select{font:inherit}button{cursor:pointer;border:1px solid #67b5ee;color:#fff;background:#124487;border-radius:8px;padding:9px 13px}button:hover{background:#2070b5}button:disabled{opacity:.45;cursor:default}input,textarea,select{color:#fff;background:#0b2550;border:1px solid #638bbc;border-radius:6px;padding:9px;max-width:100%}textarea{width:100%;min-height:70px}label{display:grid;gap:5px;margin:5px 0;color:#bad7fb}header{display:flex;gap:12px;align-items:center;flex-wrap:wrap;padding:12px 18px;background:#0a2858;border-bottom:2px solid #d4b44a}header h1{font-size:20px;margin:0 auto 0 0}header a{color:#ffdf68}.wrap{max-width:1450px;margin:auto;padding:18px}.columns{display:grid;grid-template-columns:330px minmax(0,1fr);gap:16px}.card{border:1px solid #3e81bd;background:#0b2450;border-radius:12px;padding:16px;margin-bottom:14px}.card h2{margin:0 0 12px;font-size:19px;color:#ffde70}.row{display:flex;flex-wrap:wrap;gap:7px;margin:10px 0}.row>*{flex:1}.danger{background:#85314b}.gold{background:#9b7124}.notice{color:#ffdf80;min-height:22px}.muted{color:#abc6e5;font-size:14px}.scoregrid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.person{padding:10px;background:#0b3577;border:2px solid #5ec8e6;text-align:center;min-width:0}.person.active{border-color:#ffe368;box-shadow:0 0 20px #ffd760}.person img{width:62px;height:62px;object-fit:cover;border-radius:50%;display:block;margin:0 auto}.person strong{display:block;font-size:22px;color:#ffe574}.person span{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.stage{position:relative;aspect-ratio:16/9;overflow:hidden;border:3px solid #edc863;background:radial-gradient(circle at 50% 15%,#1553a4,#061e56 58%,#071020);box-shadow:0 10px 35px #0007}.stage.obstacle,.stage.speed{background:radial-gradient(circle at 25% 30%,#0e90d1,#0b316d 60%,#02152e)}.stage.finish{background:radial-gradient(circle at 48% 27%,#71344f,#111a3c 57%,#080e20)}.stage-head{position:absolute;left:4%;right:4%;top:3%;height:13%;display:flex;align-items:center;border-bottom:2px solid #f5d26a;gap:1vw;font-size:clamp(14px,2.1vw,34px);font-weight:900;text-shadow:0 0 15px #79c9ff}.stage-head img{max-height:100%;width:10%;object-fit:contain}.stage-title{margin-left:auto;color:#ffdc69;font-size:clamp(12px,1.6vw,24px)}.stage-main{position:absolute;top:19%;bottom:20%;left:6%;right:6%;display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center;gap:2%}.intro-text{font-size:clamp(28px,6.5vw,104px);color:#ffe181;font-weight:1000;text-shadow:0 0 22px #f08157}.prompt{width:100%;background:#07346ecc;border:2px solid #79d8fd;padding:2%;font-size:clamp(18px,3vw,48px);font-weight:850;white-space:pre-wrap}.media{max-height:55%;max-width:80%;object-fit:contain}.clock{position:absolute;right:2%;top:18%;border:3px solid #ffde65;border-radius:50%;background:#09275a;width:8%;aspect-ratio:1;display:grid;place-items:center;font-size:clamp(17px,3vw,49px);font-weight:950}.stage-scores{position:absolute;left:3%;right:3%;bottom:3%;height:16%;display:grid;grid-template-columns:repeat(4,1fr);gap:1%}.stage-scores .person{display:flex;align-items:center;justify-content:center;gap:4px;flex-direction:column;padding:2px}.stage-scores .person img{width:20%;height:40%}.stage-scores .person strong{font-size:clamp(16px,2.7vw,42px)}.stage-scores .person span{font-size:clamp(10px,1.5vw,23px)}.banner{background:#043c8b;border:2px solid #ffe064;padding:1%;font-size:clamp(14px,2.4vw,35px);font-weight:900;animation:flash .35s alternate 4}@keyframes flash{to{filter:brightness(2)}}.puzzle{display:grid;grid-template-columns:repeat(2,1fr);width:60%;height:65%;gap:3px}.puzzle div{background:#0b55a1;border:2px solid #72d4fa;display:grid;place-items:center;font-size:clamp(17px,3vw,45px);font-weight:900}.puzzle div.open{background:#1a778f}.pack{display:flex;gap:2%;font-size:clamp(24px,4vw,70px);font-weight:900}.pack span{border:2px solid #ffd961;background:#0e4189;padding:1vw 3vw}.pack .active{background:#ad7b24}.result-list{width:100%;display:grid;gap:8px}.result-list div{display:grid;grid-template-columns:1fr 1fr 1fr 1fr;gap:5px;padding:1%;background:#0c4289;border:1px solid #62cef7;font-size:clamp(12px,2vw,28px)}.player-wrap{max-width:580px;margin:30px auto;padding:18px}.player-wrap .card{padding:24px}.player-wrap button{min-height:52px}.buzz{width:100%;height:135px;border-radius:50%;background:radial-gradient(#ff6b65,#ab1231);border:6px solid #ffbd77;font-size:30px;font-weight:900;box-shadow:0 9px 0 #5c1b2c}.links a{display:block;color:#b8e7ff;margin:6px 0;word-break:break-all}.assetgrid{display:grid;grid-template-columns:repeat(2,1fr);gap:6px}.assetgrid input{width:100%}@media(max-width:850px){.columns{grid-template-columns:1fr}.scoregrid{grid-template-columns:repeat(2,1fr)}.stage-scores{height:19%}}

