.stage-main:has(.camera-layout) .banner{position:absolute;top:9%;left:12%;right:12%;z-index:2}
.stage.speed .stage-main{left:12%;right:12%}.stage.speed .prompt{background:#063879;border-radius:0}.stage.speed .result-list div{clip-path:polygon(2% 0,98% 0,100% 50%,98% 100%,2% 100%,0 50%);background:linear-gradient(90deg,#06214f 35%,#164aab 35% 80%,#06214f 80%)}
.stage.obstacle .puzzle{position:relative;border:3px solid #b6eaff}.stage.obstacle .puzzle:after{content:"5";position:absolute;left:38%;top:37%;width:24%;height:26%;display:grid;place-items:center;background:#083b80;border:2px solid #a0ecff;color:#fff;font-size:clamp(19px,3vw,46px);font-weight:950}.stage.obstacle .puzzle.final-open:after{opacity:.12}
@media(max-width:850px){.camera-portrait img{max-width:75%}.camera-layout .question-ribbon{font-size:clamp(13px,3vw,30px)}}
