</aside><section><div class="card"><h2>Soạn câu hỏi</h2><div class="row"><label>Số câu<input id="number" type="number" min="1" max="12" value="1"></label><label>Thí sinh đang thi<select id="seat"></select></label><label>Khởi động<select id="mode"><option value="private">6 câu riêng</option><option value="common">12 câu chung</option></select></label></div><label>Loại câu hỏi<select id="kind"><option value="normal">Câu hỏi thường</option><option value="practice">Thực hành Về đích</option></select></label><label>Nội dung<textarea id="question"></textarea></label><label>Đáp án chuẩn<input id="answer"></label><label>Đường dẫn ảnh/video câu hỏi<input id="media" placeholder="Tải ảnh phía dưới hoặc nhập URL"></label><div class="row"><button id="setQuestion">Hiện câu hỏi</button><button id="startTimer">Tính thời gian</button><button id="practiceTimer">Bắt đầu thực hành</button><button id="stopTimer">Kết thúc câu hỏi</button><button id="reveal">Công bố đáp án</button></div></div>
