<script>
const MODE=<?=json_encode($mode)?>,CSRF=<?=json_encode($csrf)?>;let code=<?=json_encode($code)?>,state=null,rev=-1,seat=null,lastEvent=-1,serverOffset=0,waiting=false,soundEnabled=MODE!=='screen',hostFieldsLoaded=false;
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const titles={khoi_dong:'KHỞI ĐỘNG',vuot_chuong_ngai_vat:'VƯỢT CHƯỚNG NGẠI VẬT',tang_toc:'TĂNG TỐC',ve_dich:'VỀ ĐÍCH',cau_hoi_phu:'CÂU HỎI PHỤ'};
async function api(action,data={}){let form=new FormData();form.set('action',action);form.set('csrf',CSRF);form.set('code',code);Object.entries(data).forEach(([k,v])=>form.set(k,v));let r=await fetch('olympia_stage_api.php',{method:'POST',body:form,credentials:'same-origin'});let j=await r.json();if(!j.ok)throw Error(j.message||'Thao tác không thành công');return j}
function notice(e){if($('message'))$('message').textContent=e.message||String(e);else alert(e.message||String(e))}
function act(a,data){api(a,data).then(j=>{state=j.state;render()}).catch(notice)}
function portrait(i){return state?.portraits?.[i]?`<img src="${esc(state.portraits[i])}" alt="Ảnh thí sinh">`:''}
function scores(){return(state?.names||[]).map((n,i)=>`<div class="person ${state.seat===i?'active':''}">${portrait(i)}<span>${esc(n)}</span><strong>${state.scores[i]}</strong></div>`).join('')}
function remaining(){return state?.timer_end?Math.max(0,Math.ceil((state.timer_end-(Date.now()+serverOffset))/1000)):state?.timer_seconds??0}
function stageHTML(){if(!state)return '<div class="card">Chưa mở phiên.</div>';let round=state.round,scene=state.scene,h='';
 if(scene==='intro'||scene==='finished')h=`<div class="intro-text">${scene==='finished'&&state.tie_winner!==null?'THẮNG CÂU HỎI PHỤ':scene==='finished'?'KẾT THÚC':titles[round]}</div><div>${state.tie_winner!==null&&round==='cau_hoi_phu'?esc(state.names[state.tie_winner]):'ĐƯỜNG LÊN ĐỈNH OLYMPIA · SÂN KHẤU 26'}</div><div class="scoregrid" style="width:90%">${scores()}</div>`;
 else if(scene==='pack')h=`<div class="intro-text">CHỌN GÓI CÂU HỎI</div><div class="pack">${state.pack.map((n,i)=>`<span class="${i===state.pack_index?'active':''}">${n}</span>`).join('')}</div><div>Tổng ${state.pack.reduce((a,b)=>a+b,0)} điểm · ${esc(state.names[state.seat])}</div>`;
 else if(scene==='puzzle'||scene==='image')h=`<div class="puzzle ${state.puzzle_open[4]?'final-open':''}" style="background:${state.puzzle_image?`url('${esc(state.puzzle_image)}') center/cover`:''}">${state.puzzle_open.slice(0,4).map((open,i)=>`<div class="${open?'open':''}">${open?'':i+1}</div>`).join('')}</div><div class="result-list" style="grid-template-columns:repeat(4,1fr);gap:4px">${state.puzzle_open.slice(0,4).map((open,i)=>`<div style="display:block">${i+1} · ${open?esc(state.puzzle_words?.[i]||'ĐÃ MỞ'):'● '.repeat((state.puzzle_words?.[i]||'OLYMPIA').length)}</div>`).join('')}</div><div>Chướng ngại vật · ${state.puzzle_open.filter(Boolean).length} mảnh đã mở ${state.puzzle_open[4]?'· GỢI Ý CUỐI':''}</div>${state.buzz?`<div class="banner">🔔 ${esc(state.names[state.buzz.seat])} TRẢ LỜI CHƯỚNG NGẠI VẬT</div>`:''}`;
 else if(scene==='star')h=`<div class="intro-text">★ NGÔI SAO HY VỌNG ★</div><div>${esc(state.names[state.seat])} · câu ${state.pack_index+1} · ${state.pack[state.pack_index]} điểm</div>`;
 else if(scene==='results'&&round==='tang_toc'){
  const rows=Object.entries(state.answers).map(([i,a])=>[+i,a]).sort((a,b)=>a[1].at-b[1].at);h=`<div class="result-list">${rows.map(([i,a])=>`<div><b>${esc(state.names[i])}</b><span>${esc(a.text)}</span><span>${((a.elapsed_ms||0)/1000).toFixed(2)}s</span><b>${a.approved?'+'+(a.awarded_points||0):'—'}</b></div>`).join('')}</div><div>Đáp án: ${esc(state.answer_key||'Đã công bố')} · Điểm theo thứ tự đúng và thời điểm trả lời</div>`;
 }else if(['khoi_dong','ve_dich'].includes(round)&&['question','results','score'].includes(scene)){
  const active=state.seat,caption=round==='khoi_dong'?(state.mode==='private'?`LƯỢT RIÊNG · ${esc(state.names[active])} · CÂU ${state.question_no}/6`:`LƯỢT CHUNG · CÂU ${state.question_no}/12 · BẤM CHUÔNG`):`${esc(state.names[active])} · CÂU ${state.pack_index+1}/3 · GÓI ${state.pack.join('–')}`;
  h=`<div class="camera-layout"><div class="camera-portrait">${state.portraits[active]?portrait(active):'HÌNH ẢNH THÍ SINH / SÂN KHẤU'}</div><div class="question-ribbon"><small>${caption}</small>${esc(state.question||'Đang chờ câu hỏi')}${state.revealed?`<div class="answer-line">ĐÁP ÁN: ${esc(state.answer_key||'Giám khảo công bố')}</div>`:''}</div>${round==='ve_dich'?`<div class="finish-value">${state.star_active?'★ ':''}${state.pack[state.pack_index]}</div>`:''}${state.buzz?`<div class="banner">🔔 ${esc(state.names[state.buzz.seat])} GIÀNH QUYỀN</div>`:''}</div>`;
 }else h=`<div class="prompt">${esc(state.question||'Đang chờ câu hỏi')}</div>${state.media?`<img class="media" src="${esc(state.media)}" alt="Hình ảnh câu hỏi">`:''}${state.buzz?`<div class="banner">🔔 ${esc(state.names[state.buzz.seat])} GIÀNH QUYỀN</div>`:''}${state.star_active?'<div class="banner">★ NGÔI SAO HY VỌNG</div>':''}${state.question_kind==='practice'?`<div class="banner">THỰC HÀNH · ${state.practice_phase==='doing'?'ĐANG THỰC HIỆN':'SUY NGHĨ'}</div>`:''}${state.revealed?`<div class="banner">ĐÁP ÁN: ${esc(state.answer_key||'Người điều khiển công bố')}</div>`:''}<div>Câu ${state.question_no}${round==='khoi_dong'?' · '+(state.mode==='private'?'LƯỢT RIÊNG':'LƯỢT CHUNG'):''}</div>`;
 return `<div class="stage ${round==='vuot_chuong_ngai_vat'?'obstacle':round==='tang_toc'?'speed':round==='ve_dich'?'finish':round==='khoi_dong'?'start':''}"><div class="stage-head">${state.logo?`<img src="${esc(state.logo)}">`:''}⛰ ĐƯỜNG LÊN ĐỈNH OLYMPIA <span class="stage-title">${titles[round]}</span></div><div class="clock" data-clock>${remaining()}</div><div class="stage-main">${h}</div><div class="stage-scores">${scores()}</div></div>`}
function playSound(){if(!state||state.event===lastEvent)return;lastEvent=state.event;let key=state.event_name,url=state.sounds?.[key]||state.sounds?.[state.round];if(url&&soundEnabled){new Audio(url).play().catch(()=>{})}}
function render(){if(!state)return;playSound();if($('preview'))$('preview').innerHTML=stageHTML();if(MODE==='host')renderHost();if(MODE==='player')renderPlayer();$('connection').textContent=`Phiên ${code} · trực tuyến`}
function renderHost(){if(!hostFieldsLoaded){document.querySelectorAll('.nameInput').forEach((x,i)=>x.value=state.names[i]);document.querySelectorAll('.packChoice').forEach((x,i)=>x.value=state.pack[i]);hostFieldsLoaded=true}if($('round'))$('round').value=state.round;let box=$('answers');box.innerHTML=state.names.map((n,i)=>{let a=state.answers[i];return `<div class="row"><b>${esc(n)} (${state.scores[i]})</b><span>${a?esc(a.text)+' · '+((a.elapsed_ms||0)/1000).toFixed(2)+'s':'Chưa trả lời'}</span><button data-judge="${i}:1">Đúng</button><button class="danger" data-judge="${i}:0">Sai</button></div>`}).join('');box.querySelectorAll('[data-judge]').forEach(b=>b.onclick=()=>{let [seat,correct]=b.dataset.judge.split(':');act('judge',{seat,correct,type:state.round==='vuot_chuong_ngai_vat'&&state.buzz?'obstacle':'horizontal'})});$('star').disabled=state.star_used[state.seat]||!['pack','star'].includes(state.scene);$('star').textContent=state.star_active?'★ Đã đặt Ngôi sao':'★ Đặt Ngôi sao trước câu hỏi';$('packIndex').value=state.pack_index;$('seat').value=state.seat;document.querySelectorAll('.tieChoice').forEach(x=>x.checked=state.tie_candidates?.includes(+x.value)||false);$('finishNext').disabled=state.round!=='ve_dich'||state.scene==='finished'}
function renderPlayer(){if(seat===null)return;$('joinBox').hidden=true;$('playerBox').hidden=false;$('playerName').textContent=state.names[seat];$('playerPrompt').textContent=state.question||'Đang chờ người dẫn chương trình';$('playerScores').innerHTML=scores();$('buzz').disabled=!['question','results','puzzle','image'].includes(state.scene)||!!state.buzz||!['khoi_dong','vuot_chuong_ngai_vat','ve_dich','cau_hoi_phu'].includes(state.round)||(state.scene==='results'&&state.round!=='ve_dich')||(['puzzle','image'].includes(state.scene)&&state.round!=='vuot_chuong_ngai_vat')||(state.round==='khoi_dong'&&state.mode!=='common')||(state.round==='ve_dich'&&(state.seat===seat||!state.steal_open))||!!state.eliminated[seat];$('myStatus').textContent=state.buzz?`Chuông: ${state.names[state.buzz.seat]}`:state.my_answer?'Đã gửi: '+state.my_answer.text:''}
async function poll(){if(!code||waiting)return;waiting=true;try{let r=await fetch(`olympia_stage_api.php?action=state&code=${encodeURIComponent(code)}`,{cache:'no-store',credentials:'same-origin'}),j=await r.json();if(j.ok){serverOffset=j.server_ms-Date.now();seat=j.seat;if(j.revision!==rev){rev=j.revision;state=j.state;render()}$('connection').textContent=`Phiên ${code} · trực tuyến`}else $('connection').textContent=j.message}catch(e){$('connection').textContent='Mất kết nối · đang thử lại'}finally{waiting=false}}
setInterval(()=>{document.querySelectorAll('[data-clock]').forEach(el=>el.textContent=remaining());if($('playerClock'))$('playerClock').textContent=state?.timer_end?'Thời gian còn: '+remaining()+' giây':''},200);setInterval(poll,500);
if(MODE==='host'){
 $('newNames').innerHTML=[0,1,2,3].map(i=>`<label>Thí sinh ${i+1}<input class="newName" value="Thí sinh ${i+1}"></label>`).join('');
 $('create').onclick=async()=>{try{let j=await api('create',{names:JSON.stringify([...document.querySelectorAll('.newName')].map(x=>x.value))});code=j.code;hostFieldsLoaded=false;$('codeInput').value=code;$('codes').innerHTML=`Mã phiên <b>${code}</b><br>`+j.pins.map((p,i)=>`Ghế ${i+1}: <b>${p}</b>`).join(' · ');history.replaceState(null,'',`?view=host&code=${code}`);updateLinks();poll()}catch(e){notice(e)}};
 $('openRoom').onclick=()=>{code=$('codeInput').value.trim();hostFieldsLoaded=false;history.replaceState(null,'',`?view=host&code=${encodeURIComponent(code)}`);updateLinks();poll()};
 function updateLinks(){if(!code)return;let root=location.href.split('?')[0];$('links').innerHTML=`<a href="${root}?view=screen&code=${code}" target="_blank">Mở màn trình chiếu</a><a href="${root}?view=player&code=${code}" target="_blank">Đường dẫn máy thí sinh</a>`}updateLinks();
 $('setRound').onclick=()=>act('round',{round:$('round').value});$('scenes').innerHTML=[['intro','Mở vòng'],['question','Câu hỏi'],['pack','Gói'],['star','Ngôi sao'],['puzzle','Ô chữ'],['image','Hình ảnh'],['results','Kết quả'],['score','Điểm'],['finished','Kết thúc']].map(([v,t])=>`<button data-scene="${v}">${t}</button>`).join('');$('scenes').onclick=e=>{let b=e.target.closest('[data-scene]');if(b)act('scene',{scene:b.dataset.scene})};
 $('seat').innerHTML=[0,1,2,3].map(i=>`<option value="${i}">Thí sinh ${i+1}</option>`).join('');$('nameInputs').innerHTML=[0,1,2,3].map(i=>`<label>Thí sinh ${i+1}<input class="nameInput" value="Thí sinh ${i+1}"></label>`).join('');$('saveNames').onclick=()=>act('setup',{names:JSON.stringify([...document.querySelectorAll('.nameInput')].map(x=>x.value))});
 $('setQuestion').onclick=()=>act('question',{question:$('question').value,answer:$('answer').value,media:$('media').value,number:$('number').value,seat:$('seat').value,mode:$('mode').value,kind:$('kind').value});$('startTimer').onclick=()=>act('timer');$('practiceTimer').onclick=()=>act('practice_timer');$('stopTimer').onclick=()=>act('stop');$('reveal').onclick=()=>act('reveal');$('undoJudge').onclick=()=>{if(confirm('Hoàn tác lần chấm gần nhất?'))act('undo_judge')};$('resetBuzz').onclick=()=>act('reset_buzz');$('star').onclick=()=>act('star');
 $('tieChoices').innerHTML=[0,1,2,3].map(i=>`<label><input type="checkbox" class="tieChoice" value="${i}">Ghế ${i+1}</label>`).join('');$('saveTie').onclick=()=>act('tie_candidates',{seats:JSON.stringify([...document.querySelectorAll('.tieChoice:checked')].map(x=>+x.value))});
 $('wordInputs').innerHTML=[0,1,2,3].map(i=>`<label>Hàng ngang ${i+1}<input class="puzzleWord"></label>`).join('');$('savePuzzle').onclick=()=>act('puzzle_config',{words:JSON.stringify([...document.querySelectorAll('.puzzleWord')].map(x=>x.value))});
 $('packChoices').innerHTML=[0,1,2].map(i=>`<label>Câu ${i+1}<select class="packChoice"><option value="20">20 điểm</option><option value="30">30 điểm</option></select></label>`).join('');$('savePack').onclick=()=>act('pack',{pack:JSON.stringify([...document.querySelectorAll('.packChoice')].map(x=>+x.value))});$('packIndex').onchange=()=>act('pack_index',{index:$('packIndex').value});$('finishNext').onclick=()=>{if(confirm('Kết thúc lượt Về đích của '+state.names[state.seat]+' và chuyển người tiếp theo?'))act('finish_next')};$('puzzlePiece').onclick=()=>{let piece=prompt('Mở mảnh ghép số mấy? (1–5)','1');if(piece&&+piece>=1&&+piece<=5)act('puzzle',{piece:+piece-1,open:1})};
 let assets=[['logo','Logo','image'],['portrait_0','Ảnh thí sinh 1','image'],['portrait_1','Ảnh thí sinh 2','image'],['portrait_2','Ảnh thí sinh 3','image'],['portrait_3','Ảnh thí sinh 4','image'],['puzzle_image','Ảnh chướng ngại vật','image'],['media','Ảnh câu hỏi','image'],...['round','question','timer','buzz','reveal','score','star','stop'].map(x=>[x,'Nhạc '+x,'sound'])];$('assets').innerHTML=assets.map(([k,t,type])=>`<label>${t}<input type="file" data-key="${k}" data-kind="${type}" accept="${type==='image'?'image/png,image/jpeg,image/webp':'audio/mpeg,audio/ogg,audio/wav'}"></label>`).join('');$('assets').onchange=async e=>{let x=e.target;if(!x.files?.[0])return;try{let form=new FormData();form.set('action','asset');form.set('csrf',CSRF);form.set('code',code);form.set('key',x.dataset.key);form.set('kind',x.dataset.kind);form.set('file',x.files[0]);let j=await(await fetch('olympia_stage_api.php',{method:'POST',body:form,credentials:'same-origin'})).json();if(!j.ok)throw Error(j.message);state=j.state;render()}catch(e){notice(e)}};
}else if(MODE==='player'){$('join').onclick=async()=>{code=$('codeInput').value.trim();try{let j=await api('join',{seat:$('seatJoin').value,pin:$('pin').value});seat=j.seat;history.replaceState(null,'',`?view=player&code=${code}`);poll()}catch(e){notice(e)}};$('buzz').onclick=()=>act('buzz');$('submitAnswer').onclick=()=>act('submit',{answer:$('myAnswer').value})}
if(MODE==='screen')$('enableSound').onclick=()=>{soundEnabled=true;$('enableSound').remove();$('preview').requestFullscreen?.().catch(()=>{});new Audio().play().catch(()=>{})};
poll();
</script></body></html>
